const m = { kind:"marketing", text:"Sale! Reply STOP to opt out" };
const t = { kind:"transactional", text:"Your code is 123456" };
const D = (s)=>new Date(s);
const cases = [
 ["mkt Chicago 15:00 UTC=10:00 CDT", u(), m, D("2026-07-01T15:00:00Z"), true],
 ["mkt Chicago 13:00Z=08:00 CDT ok", u(), m, D("2026-07-01T13:00:00Z"), true],
 ["mkt Chicago 12:59Z=07:59 CDT hold", u(), m, D("2026-07-01T12:59:00Z"), "quiet-hours"],
 ["mkt Chicago 01:59Z=20:59 CDT ok", u(), m, D("2026-07-02T01:59:00Z"), true],
 ["mkt Chicago 02:00Z=21:00 CDT hold", u(), m, D("2026-07-02T02:00:00Z"), "quiet-hours"],
 ["winter: 14:00Z=08:00 CST ok", u(), m, D("2026-01-15T14:00:00Z"), true],
 ["winter: 13:59Z=07:59 CST hold", u(), m, D("2026-01-15T13:59:00Z"), "quiet-hours"],
