 ["Kolkata 16:00Z=21:30 hold", u({timeZone:"Asia/Kolkata"}), m, D("2026-07-01T16:00:00Z"), "quiet-hours"],
 ["tz null", u({timeZone:null}), m, D("2026-07-01T15:00:00Z"), "unknown-local-time"],
 ["tz bogus", u({timeZone:"Mars/Base"}), m, D("2026-07-01T15:00:00Z"), "unknown-local-time"],
 ["tz UTC", u({timeZone:"UTC"}), m, D("2026-07-01T15:00:00Z"), "unknown-local-time"],
 ["tz number", u({timeZone:5}), m, D("2026-07-01T15:00:00Z"), "unknown-local-time"],
 ["not opted in", u({sms:{optedIn:false,optedOutAt:null}}), m, D("2026-07-01T15:00:00Z"), "no-consent"],
 ["opted out mkt", u({sms:{optedIn:true,optedOutAt:"2026-06-01T00:00:00Z"}}), m, D("2026-07-01T15:00:00Z"), "opted-out"],
 ["opted out txn", u({sms:{optedIn:true,optedOutAt:"2026-06-01T00:00:00Z"}}), t, D("2026-07-01T15:00:00Z"), "opted-out"],
 ["opted out garbage", u({sms:{optedIn:true,optedOutAt:"garbage"}}), t, D("2026-07-01T15:00:00Z"), "opted-out"],
 ["txn at 3am no consent flag, bad tz", u({timeZone:null,sms:{optedIn:false,optedOutAt:null}}), t, D("2026-07-01T08:00:00Z"), true],
 ["txn bad now", u(), t, new Date(NaN), true],
 ["mkt bad now", u(), m, new Date(NaN), "invalid-time"],
 ["mkt now string", u(), m, "2026-07-01T15:00:00Z", "invalid-time"],
 ["bad kind", u(), {kind:"promo",text:"x"}, D("2026-07-01T15:00:00Z"), "invalid-message"],
 ["empty text", u(), {kind:"marketing",text:"  "}, D("2026-07-01T15:00:00Z"), "invalid-message"],
 ["null user", null, m, D("2026-07-01T15:00:00Z"), "invalid-user"],
 ["no sms", {id:"1"}, m, D("2026-07-01T15:00:00Z"), "invalid-user"],
 ["null message", u(), null, D("2026-07-01T15:00:00Z"), "invalid-message"],
];
let bad=0;
for (const [n,user,msg,now,exp] of cases){
  const r = await checkSend({user,message:msg,now});
  const ok = exp===true ? (r.allowed&&r.rule==="") : (!r.allowed&&r.rule===exp);
  if(!ok){bad++;console.log("FAIL",n,r)}
}
for (const a of [undefined,null,{},[],"x",{user:{get sms(){throw 1}},message:m,now:new Date()}]) {
  try { const r = await checkSend(a); if(r.allowed) {bad++;console.log("FAIL allowed",a)} } catch(e){bad++;console.log("THROW",a)}
}
console.log(bad?`${bad} failed`:`all ${cases.length}+6 passed`);
